import{K as r,a as l,c as i,b as a,k as n,q as s,ac as c}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Word 表格制作与跨页排版","description":"建立和调整 Word 表格，控制列宽、单元格边距、跨页重复表头、行拆分、题注与表后空白页，完成会议行动清单。","frontmatter":{"title":"Word 表格制作与跨页排版","description":"建立和调整 Word 表格，控制列宽、单元格边距、跨页重复表头、行拆分、题注与表后空白页，完成会议行动清单。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Word 文档排版","summary":"建立和调整 Word 表格，控制列宽、单元格边距、跨页重复表头、行拆分、题注与表后空白页，完成会议行动清单。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Word 分节、页眉页脚与页码","link":"/tools/office/word/sections"},"next":{"text":"Word 图片、题注、交叉引用与参考文献","link":"/tools/office/word/images-references"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Word 分节、页眉页脚与页码","link":"/tools/office/word/sections"},"next":{"text":"Word 图片、题注、交叉引用与参考文献","link":"/tools/office/word/images-references"}},"headers":[],"relativePath":"tools/office/word/tables.md","filePath":"tools/office/word/tables.md"}'),d={name:"tools/office/word/tables.md"},k=Object.assign(d,{setup(h){const o={path:"/tools/office/word/tables",app:"Word",title:"做一张跨页仍有表头的行动清单",steps:[{tab:"插入",command:"表格",setting:"4 列：事项 / 负责人 / 截止日期 / 状态",anchor:"walkthrough-1"},{tab:"表格布局",command:"重复标题行",setting:"选中首行；在后续页面显示表头",anchor:"walkthrough-2"},{tab:"表格布局",command:"属性",setting:"行：按需关闭允许跨页断行；表格宽度适合页面",anchor:"walkthrough-3"}]};return(p,e)=>{const t=r("OfficeGuide");return l(),i("div",null,[e[0]||(e[0]=a("h1",{id:"word-表格制作与跨页排版",tabindex:"-1"},[n("Word 表格制作与跨页排版 "),a("a",{class:"header-anchor",href:"#word-表格制作与跨页排版","aria-label":'Permalink to "Word 表格制作与跨页排版"'},"​")],-1)),e[1]||(e[1]=a("p",null,"Word 表格适合在文档中组织信息，不适合承担持续更新的复杂计算。需要公式、筛选和统计时先在 Excel 完成，再选择合适方式引用到 Word。",-1)),s(t,{guide:o}),e[2]||(e[2]=c('<h2 id="create" tabindex="-1">建立行动清单 <a class="header-anchor" href="#create" aria-label="Permalink to &quot;建立行动清单 {#create}&quot;">​</a></h2><p>使用“插入 → 表格”创建五列：编号、事项、负责人、截止日期、状态。输入三条虚构任务，再从表格末尾按 <code>Tab</code> 添加新行；要在单元格内部插入制表符，桌面版通常使用 <code>Ctrl+Tab</code>。</p><p>长表格不要用合并单元格重复做分组标题。合并会使跨页、排序和屏幕阅读更复杂；相同类别可以单独增加“类别”列。只有表格标题等确有需要的地方再使用合并。</p><h2 id="width" tabindex="-1">列宽与内容适配 <a class="header-anchor" href="#width" aria-label="Permalink to &quot;列宽与内容适配 {#width}&quot;">​</a></h2><ol><li>选中表格，在“表格布局 → 自动调整”选择按窗口调整，让总宽度进入版心。</li><li>给“事项”分配更多宽度，编号和日期保持适当窄度。</li><li>需要稳定打印时切换为固定列宽，并检查“表格属性”中的宽度设置。</li><li>在“单元格边距”中留出适量内边距，不用手动输入空格制造留白。</li><li>根据内容设置垂直对齐；长文本一般顶部对齐更容易逐行阅读。</li></ol><p>行高使用最小值通常更能适应内容；固定值可能截断多行文字。若单元格看起来上下空白过大，检查其中段落的段前段后，不要只缩小行高。</p><h2 id="pages" tabindex="-1">跨页表头与行拆分 <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;跨页表头与行拆分 {#pages}&quot;">​</a></h2><p>选中表格第一行，在“表格布局 → 重复标题行”启用重复表头。该功能用于同一张表自动跨页时重复显示表头；把表拆成两张独立表不会自动保持表头一致。表内手动插入分页也可能影响期望的重复行为，应优先让表格自然分页。</p><p>在“表格属性 → 行”检查“允许跨页断行”。短任务条目可取消，让一条记录保持完整；单条记录本身长于一页时，应允许合理拆分或改成正文说明，否则页面留白和布局会异常。标题行中的段落若设置“与下段同页”，也要确认没有把全表连成一块。</p><h2 id="caption" tabindex="-1">表格位置与题注 <a class="header-anchor" href="#caption" aria-label="Permalink to &quot;表格位置与题注 {#caption}&quot;">​</a></h2><p>表格属性中的文字环绕若设为“无”，表格随正文流动，通常适合正式报告。设置为环绕时可以更自由定位，但会增加移动与跨页的不确定性。表格不是图片，不需要用很多空段落把它推到想要的位置。</p><p>为重要表格使用“引用 → 插入题注”，例如“表 1 培训行动清单”。在正文用交叉引用引用表号，表格增加或移动后更新字段；不要手写所有编号。题注应靠近表格，表下注明单位、范围和数据来源。</p><h2 id="problems" tabindex="-1">常见故障 <a class="header-anchor" href="#problems" aria-label="Permalink to &quot;常见故障 {#problems}&quot;">​</a></h2><p>表格跑出页面边界：检查表格总宽度、缩进和页面方向。文字被裁掉：检查行高是否固定、单元格边距和段落行距。最后多出空白页：查看表后必须存在的段落标记是否被挤到下一页，可在不影响可读性的前提下调整表格大小或该段落的字号和间距；不要盲目删除附近分节符。</p><p>如果表格内容非常宽，先删去不必要列或把备注移到正文，确有需要再使用<a href="/tools/office/word/sections#landscape">横向分节页面</a>。缩小到无法阅读不是有效解决方法。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>将行动清单扩展到两页，设置重复表头、固定列宽和表格题注。在一条任务中加入较长说明，分别测试允许和禁止跨页断行，观察分页。最后导出 PDF，第二页应有表头，文字不被裁切，表号和正文引用一致。</p><p>参考入口：<a href="https://support.microsoft.com/en-us/word/" target="_blank" rel="noopener noreferrer">Word 帮助与学习</a>。</p><h2 id="walkthrough" tabindex="-1">图示跟做：做一张跨页仍有表头的行动清单 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：做一张跨页仍有表头的行动清单 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：创建结构清楚的清单 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：创建结构清楚的清单 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：插入 → 表格。</strong></p><p>选择“插入 → 表格”，建立四列表格，第一行写字段名，下面录入十几条虚构待办。需要新增一行时在最后一个单元格按 Tab，观察表格扩展。日期统一写法；同一项需要多段说明时在该格内部换段，不用另建不相干的表格。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：让跨页内容可识别 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：让跨页内容可识别 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：表格布局 → 重复标题行。</strong></p><p>选中第一行，点击选中表格后出现的“布局”或“表格布局 → 重复标题行”。增加内容直到表格自然跨页，进入打印布局查看第二页。表头重复发生在分页显示中；在表格内人为插入分页符可能影响效果，应优先让 Word 自动分页。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：处理断行和过宽 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：处理断行和过宽 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：表格布局 → 属性。</strong></p><p>打开表格属性，在行选项中按需要取消允许跨页断行，让一项待办完整出现在同一页。长到超过一页的单行不适合强行禁止拆分，应拆成更清楚的记录。最后检查列宽和页面宽度，导出 PDF 看右侧状态列是否完整。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>第二页没有表头时，先确认首行确实属于同一张表，选中范围包含表的第一行。表格后出现空白页时显示段落标记，检查表后段落和分页设置，先在副本中调整。</p>',31))])}}});export{u as __pageData,k as default};
